import React, { useEffect, useState } from 'react';
import Masonry from 'react-masonry-css';
import './MasonryGrid.css';

// Define types based on our editorial data structure
export interface EditorialImage {
  url: string;
  alt: string;
  caption?: string;
}

export interface GalleryImage {
  image: EditorialImage;
  caption?: string;
  aspectRatio: 'square' | 'portrait' | 'landscape' | 'wide' | 'full-width';
  priority: number;
}

export interface Editorial {
  id: string;
  title: string;
  slug: string;
  author: string;
  publishedDate: string;
  category: string;
  displayType: 'gallery' | 'article';
  featuredImage: EditorialImage;
  summary?: string;
  content?: any;
  galleryImages?: GalleryImage[];
}

interface MasonryGridProps {
  editorials: Editorial[];
  onCategorySelect?: (category: string) => void;
  selectedCategory?: string;
}

// Define proper types for Masonry component
interface MasonryBreakpoints {
  default: number;
  [key: number]: number;
}

const MasonryGrid: React.FC<MasonryGridProps> = ({ 
  editorials, 
  onCategorySelect,
  selectedCategory = 'all'
}) => {
  const [isLoading, setIsLoading] = useState(true);
  const [items, setItems] = useState<Editorial[]>([]);

  useEffect(() => {
    if (editorials && editorials.length > 0) {
      setItems(editorials);
      setIsLoading(false);
    }
  }, [editorials]);

  const breakpointColumnsObj: MasonryBreakpoints = {
    default: 3,
    1100: 2,
    700: 1
  };

  if (isLoading) {
    return <div className="loading">Loading editorials...</div>;
  }

  // Get display image based on editorial type
  const getDisplayImage = (editorial: Editorial): EditorialImage => {
    if (editorial.displayType === 'gallery' && editorial.galleryImages && editorial.galleryImages.length > 0) {
      // Sort gallery images by priority if needed
      const sortedImages = [...editorial.galleryImages].sort((a, b) => b.priority - a.priority);
      return sortedImages[0].image;
    }
    return editorial.featuredImage;
  };

  // Get aspect ratio class
  const getAspectRatioClass = (editorial: Editorial): string => {
    if (editorial.displayType === 'gallery' && editorial.galleryImages && editorial.galleryImages.length > 0) {
      const sortedImages = [...editorial.galleryImages].sort((a, b) => b.priority - a.priority);
      return sortedImages[0].aspectRatio;
    }
    return 'square'; // Default aspect ratio
  };

  return (
    <div className="masonry-container">
      <Masonry
        breakpointCols={breakpointColumnsObj}
        className="masonry-grid"
        columnClassName="masonry-grid_column"
      >
        {items.map((editorial) => {
          const displayImage = getDisplayImage(editorial);
          const aspectRatio = getAspectRatioClass(editorial);
          
          return (
            <div 
              key={editorial.id} 
              className={`masonry-item ${aspectRatio}`}
              data-category={editorial.category}
            >
              <a href={`/editorial/${editorial.slug}`} className="editorial-link">
                <div className="editorial-card">
                  <div className="editorial-image">
                    <img src={displayImage.url} alt={displayImage.alt || editorial.title} />
                  </div>
                  <div className="editorial-content">
                    <h2>{editorial.title}</h2>
                    <p className="editorial-meta">
                      {new Date(editorial.publishedDate).toLocaleDateString()} • {editorial.author}
                    </p>
                    {editorial.summary && (
                      <div className="editorial-excerpt">
                        {editorial.summary}
                      </div>
                    )}
                    <div className="editorial-category">
                      {editorial.category.replace(/-/g, ' ').replace(/\b\w/g, (l: string) => l.toUpperCase())}
                    </div>
                  </div>
                </div>
              </a>
            </div>
          );
        })}
      </Masonry>
    </div>
  );
};

export default MasonryGrid; 